package ru.fkit.bi.analytics.machine;

import java.util.*;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionTemplate;
import ru.fkit.bi.analytics.api.BusinessException;
import ru.fkit.bi.analytics.machine.MachineModels.*;
import ru.fkit.bi.analytics.stateconfiguration.StateConfigurationService;

@Service
class MachineService {
  private final MachineRepository repository; private final TransactionTemplate transactions; private final StateConfigurationService stateConfigurations;
  MachineService(MachineRepository repository,TransactionTemplate transactions,StateConfigurationService stateConfigurations){this.repository=repository;this.transactions=transactions;this.stateConfigurations=stateConfigurations;}
  Page<Machine> enterprisePage(UUID e,UUID line,String assignment,String status,String search,int p,int z){return page(e,line,assignment,status,search,p,z);}
  Page<Machine> linePage(UUID line,String status,String search,int p,int z){if(!repository.lineExists(line))throw missing("Line");UUID enterprise=repository.lineEnterprise(line);return page(enterprise,line,"ASSIGNED",status,search,p,z);}
  private Page<Machine> page(UUID e,UUID line,String assignment,String status,String search,int p,int z){validatePage(status,p,z);if(!Set.of("ALL","ASSIGNED","UNASSIGNED").contains(assignment))throw new BusinessException(400,"INVALID_ASSIGNMENT_FILTER","assignment must be ALL, ASSIGNED or UNASSIGNED");if(!repository.enterpriseExists(e))throw missing("Enterprise");if(line!=null&&!repository.lineOwned(e,line))throw missing("Line");long n=repository.count(e,line,assignment,status,search);return new Page<>(repository.page(e,line,assignment,status,search,p,z),new Metadata(p,z,n,(int)((n+z-1)/z)));}
  Machine create(UUID e,Create in){if(!repository.enterpriseExists(e))throw missing("Enterprise");validateRate(in.nominalRate(),in.productionUnit());List<com.fasterxml.jackson.databind.JsonNode> parameters=validateParameters(in.parameters());if(in.lineId()!=null&&!repository.lineOwned(e,in.lineId()))throw missing("Line");if(in.lineId()==null&&in.sortOrder()!=null)throw new BusinessException(422,"SORT_ORDER_REQUIRES_LINE","sortOrder is only valid for an assigned machine");Integer order=in.sortOrder();if(in.lineId()!=null&&order==null)order=repository.nextOrder(in.lineId());Create normalized=new Create(in.code(),in.name(),in.lineId(),in.machineType(),in.inventoryNo(),in.manufacturer(),in.model(),in.commissioningYear(),in.nominalRate(),in.productionUnit(),order,parameters);try{return repository.create(UUID.randomUUID(),e,normalized);}catch(DuplicateKeyException ex){throw new BusinessException(409,"MACHINE_CODE_OR_INVENTORY_CONFLICT","Machine code or inventory number already exists in enterprise");}}
  Machine get(UUID id){return repository.find(id).orElseThrow(()->missing("Machine"));}
  List<Map<String,Object>> readinessIssues(UUID id){Machine m=get(id);List<Map<String,Object>> issues=new ArrayList<>();if(!repository.enterpriseActive(id))issues.add(issue("ENTERPRISE_DISABLED","Enterprise must be active"));if(m.lineId()==null)issues.add(issue("MACHINE_NOT_ASSIGNED","Machine must be assigned to a production line"));else if(!repository.lineActive(m.lineId()))issues.add(issue("LINE_DISABLED","Assigned production line must be active"));issues.addAll(stateConfigurations.activationErrors(id));return issues;}
  List<Map<String,Object>> readinessWarnings(UUID id){get(id);return stateConfigurations.activationWarnings(id);}
  boolean ready(UUID id){return readinessIssues(id).isEmpty();}
  Machine update(UUID id,Update in){Machine current=get(id);validateRate(in.nominalRate(),in.productionUnit());List<com.fasterxml.jackson.databind.JsonNode> parameters=validateParameters(in.parameters());if(current.lineId()==null&&in.sortOrder()!=null)throw new BusinessException(422,"SORT_ORDER_REQUIRES_LINE","sortOrder is only valid for an assigned machine");Integer order=current.lineId()!=null&&in.sortOrder()==null?repository.nextOrder(current.lineId()):in.sortOrder();Update normalized=new Update(in.name(),in.machineType(),in.inventoryNo(),in.manufacturer(),in.model(),in.commissioningYear(),in.nominalRate(),in.productionUnit(),order,parameters);try{repository.update(id,normalized);}catch(DuplicateKeyException ex){throw new BusinessException(409,"MACHINE_INVENTORY_CONFLICT","Inventory number already exists in enterprise");}return get(id);}
  Machine status(UUID id,StatusUpdate in){return transactions.execute(s->{repository.lock(id);get(id);if("ACTIVE".equals(in.status())){List<Map<String,Object>> errors=readinessIssues(id);if(!errors.isEmpty())throw new BusinessException(422,"ACTIVATION_NOT_READY","Machine configuration is not ready for activation",List.of(),Map.of("errors",errors));}repository.status(id,in.status());return get(id);});}
  List<Machine> assign(UUID line,Assignments in){return transactions.execute(s->{if(!repository.lineExists(line))throw missing("Line");UUID enterprise=repository.lineEnterprise(line);repository.lockLine(line);List<UUID> ids=in.machineIds();if(ids.size()!=new HashSet<>(ids).size())throw new BusinessException(422,"DUPLICATE_MACHINE_IDS","machineIds must be unique");List<UUID> locked=repository.lockMachines(ids);Map<UUID,Machine> found=repository.findAll(ids);List<UUID> conflicts=new ArrayList<>();for(UUID id:ids){Machine m=found.get(id);if(m==null||!m.enterpriseId().equals(enterprise)||m.lineId()!=null)conflicts.add(id);}if(!locked.containsAll(ids)||!conflicts.isEmpty())throw new BusinessException(409,"MACHINE_ASSIGNMENT_CONFLICT","Every machine must exist, belong to the line enterprise and be unassigned",List.of(),Map.of("machineIds",conflicts.isEmpty()?ids:conflicts));repository.assign(ids,line);Map<UUID,Machine> updated=repository.findAll(ids);return ids.stream().map(updated::get).toList();});}
  private void validateRate(Double rate,String unit){if((rate==null)!=(unit==null))throw new BusinessException(422,"RATE_UNIT_REQUIRED","nominalRate and productionUnit must be set together");if(unit!=null&&!repository.unitExists(unit))throw new BusinessException(422,"PRODUCTION_UNIT_INVALID","productionUnit must identify an active measurement unit");}
  private List<com.fasterxml.jackson.databind.JsonNode> validateParameters(List<com.fasterxml.jackson.databind.JsonNode> values){if(values==null||values.size()>100)throw new BusinessException(422,"INVALID_PARAMETERS","parameters must contain at most 100 entries");Set<String> codes=new HashSet<>();for(var v:values){if(v==null||!v.isObject()||!v.hasNonNull("code")||!v.hasNonNull("name")||!v.hasNonNull("valueType")||!v.has("value")||!v.hasNonNull("sortOrder"))throw new BusinessException(422,"INVALID_PARAMETER","Each parameter requires code, name, valueType, value and sortOrder");String c=v.get("code").asText();if(!c.matches("^[A-Z][A-Z0-9_]{0,63}$")||!codes.add(c))throw new BusinessException(422,"INVALID_PARAMETER_CODE","Parameter codes must be valid and unique");String type=v.get("valueType").asText();boolean ok=switch(type){case "STRING"->v.get("value").isTextual();case "NUMBER"->v.get("value").isNumber();case "BOOLEAN"->v.get("value").isBoolean();default->false;};if(!ok||!v.get("sortOrder").canConvertToInt()||v.get("sortOrder").asInt()<0||v.get("name").asText().isBlank()||v.get("name").asText().length()>200)throw new BusinessException(422,"INVALID_PARAMETER_VALUE","Parameter value, name and sortOrder must match their type constraints");if(!"NUMBER".equals(type)&&v.has("unitCode"))throw new BusinessException(422,"INVALID_PARAMETER_UNIT","unitCode is allowed only for NUMBER parameters");if(v.hasNonNull("unitCode")&&(!v.get("unitCode").isTextual()||v.get("unitCode").asText().length()>50||!repository.unitExists(v.get("unitCode").asText())))throw new BusinessException(422,"INVALID_PARAMETER_UNIT","unitCode must identify an active measurement unit");}return values.stream().sorted(Comparator.comparingInt((com.fasterxml.jackson.databind.JsonNode v)->v.path("sortOrder").asInt()).thenComparing(v->v.path("code").asText())).toList();}
  private static void validatePage(String s,int p,int z){if(!Set.of("ACTIVE","DISABLED").contains(s))throw new BusinessException(400,"INVALID_STATUS_FILTER","status must be ACTIVE or DISABLED");if(p<0||z<1||z>200)throw new BusinessException(400,"INVALID_PAGINATION","page must be non-negative and size must be 1..200");}
  private static BusinessException missing(String what){return new BusinessException(404,"NOT_FOUND",what+" not found");}
  private static Map<String,Object> issue(String code,String message){Map<String,Object> v=new LinkedHashMap<>();v.put("code",code);v.put("message",message);v.put("path",null);v.put("resourceId",null);v.put("details",Map.of());return v;}
}
